package it.cavallium.rockserver.core.common.distributed;

import java.io.*;
import java.util.*;

/** Canonical complete capture vector, bound to the path-free frozen export definition. */
public final class DatabaseExportCaptures {
    public static final int MAX_BYTES=64*1024*1024;
    public record Cohort(UUID id,UUID nodeIncarnation,UUID processIncarnation,UUID poolId,List<UUID> groups){
        public Cohort{Objects.requireNonNull(id);Objects.requireNonNull(nodeIncarnation);Objects.requireNonNull(processIncarnation);Objects.requireNonNull(poolId);var ordered=new TreeSet<UUID>(RangeDirectoryCodec.UUID_ORDER);for(var group:groups)if(!ordered.add(group))throw new IllegalArgumentException("Repeated captured cohort group");if(ordered.isEmpty() || ordered.size()>1024)throw new IllegalArgumentException("Invalid captured cohort size");groups=List.copyOf(ordered);}
    }
    private final byte[] definitionDigest;private final DatabaseBackupDefinition barrier;private final List<SnapshotFenceStatus> captures;private final List<Cohort> cohorts;private final byte[] encoded;
    public DatabaseExportCaptures(DatabaseExportDefinition definition,DatabaseBackupDefinition barrier,Collection<SnapshotFenceStatus> captures,Collection<Cohort> cohorts){
        this.definitionDigest=definition.digest();this.barrier=Objects.requireNonNull(barrier);if(!barrier.backupId().equals(definition.jobId()) || !Arrays.equals(barrier.roster().encode(),definition.roster().encode()) || barrier.domains().size()!=definition.domains().size())throw new IllegalArgumentException("Export capture roster identity changed");for(var domain:barrier.domains()){var expected=definition.domain(domain.directory().domainId());if(!Arrays.equals(RangeDirectoryCodec.encode(expected.directory()),RangeDirectoryCodec.encode(domain.directory())) || !Arrays.equals(expected.schema().digest(),domain.schema().digest()))throw new IllegalArgumentException("Export captured a different domain vector");}
        this.captures=captures.stream().sorted(Comparator.comparing(value->value.fence().fenceId(),RangeDirectoryCodec.UUID_ORDER)).toList();this.cohorts=cohorts.stream().sorted(Comparator.comparing(Cohort::id,RangeDirectoryCodec.UUID_ORDER)).toList();var expected=new HashMap<UUID,SnapshotFence>();barrier.domains().forEach(domain->domain.fences().forEach(fence->{if(expected.put(fence.fenceId(),fence)!=null)throw new IllegalArgumentException("Repeated export fence");}));var seen=new HashSet<UUID>();var groups=new HashSet<UUID>();for(var capture:this.captures){if(!seen.add(capture.fence().fenceId()) || !capture.fence().equals(expected.get(capture.fence().fenceId())) || !capture.allReady() || capture.progress().stream().anyMatch(progress->progress.capture()==null) || capture.phase()==SnapshotFenceStatus.Phase.ABORT)throw new IllegalArgumentException("Export capture vector is incomplete");for(var progress:capture.progress())if(!groups.add(progress.groupId()))throw new IllegalArgumentException("Repeated export captured group");}if(!seen.equals(expected.keySet()))throw new IllegalArgumentException("Export capture fence coverage changed");var covered=new HashSet<UUID>();var ids=new HashSet<UUID>();for(var cohort:this.cohorts){if(!ids.add(cohort.id()))throw new IllegalArgumentException("Repeated export cohort identity");for(var group:cohort.groups())if(!covered.add(group))throw new IllegalArgumentException("Export group captured twice");}if(!covered.equals(groups))throw new IllegalArgumentException("Export cohort coverage differs from token vector");
        encoded=BackupData.bytes(out->{out.writeInt(0x44455843);out.write(definitionDigest);BackupData.blob(out,barrier.encode());out.writeInt(this.captures.size());for(var capture:this.captures)BackupData.blob(out,capture.encode());out.writeInt(this.cohorts.size());for(var cohort:this.cohorts){BackupData.uuid(out,cohort.id());BackupData.uuid(out,cohort.nodeIncarnation());BackupData.uuid(out,cohort.processIncarnation());BackupData.uuid(out,cohort.poolId());out.writeInt(cohort.groups().size());for(var group:cohort.groups())BackupData.uuid(out,group);}},MAX_BYTES);
    }
    public byte[] encode(){return encoded.clone();}public int encodedBytes(){return encoded.length;}public byte[] page(long offset,int maximum){if(offset<0 || offset>encoded.length || maximum<1)throw new IllegalArgumentException("Invalid export witness page");return Arrays.copyOfRange(encoded,(int)offset,(int)Math.min(encoded.length,offset+maximum));}public byte[] digest(){return BackupData.hash(encoded);}public byte[] definitionDigest(){return definitionDigest.clone();}public DatabaseBackupDefinition barrier(){return barrier;}public List<SnapshotFenceStatus> captures(){return captures;}public List<Cohort> cohorts(){return cohorts;}
    public static DatabaseExportCaptures decode(byte[] bytes,DatabaseExportDefinition definition){return BackupData.read(bytes,MAX_BYTES,in->{if(in.readInt()!=0x44455843 || !Arrays.equals(in.readNBytes(32),definition.digest()))throw new IOException("Export capture definition digest changed");var barrier=DatabaseBackupDefinition.decode(BackupData.blob(in,DatabaseBackupDefinition.MAX_BYTES));int count=BackupData.count(in,DatabaseBackupDefinition.MAX_RANGES);var captures=new ArrayList<SnapshotFenceStatus>();for(int n=0;n<count;n++)captures.add(SnapshotFenceStatus.decode(BackupData.blob(in,SnapshotFenceStatus.MAX_BYTES)));count=BackupData.count(in,1024);var cohorts=new ArrayList<Cohort>();for(int n=0;n<count;n++){UUID id=BackupData.uuid(in),node=BackupData.uuid(in),process=BackupData.uuid(in),pool=BackupData.uuid(in);int members=BackupData.count(in,1024,16);var groups=new ArrayList<UUID>();for(int m=0;m<members;m++)groups.add(BackupData.uuid(in));cohorts.add(new Cohort(id,node,process,pool,groups));}var result=new DatabaseExportCaptures(definition,barrier,captures,cohorts);BackupData.canonical(bytes,result.encoded);return result;});}
}
